def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opps:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 60.0))
        return float(min(budget, 20.0))

    prev_bids = []
    rich_aggressive = 0
    desperate_opps = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 120:
                rich_aggressive += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opps += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (float(supply) <= 17.0)
    comfortable_supply = (float(supply) >= 22.0)

    if hp <= 1 or no_water_days >= 2:
        bid = 160.0 if scarcity else 120.0
    elif hp <= 2 or no_water_days >= 1:
        if highest_prev >= 140:
            bid = 145.0 if scarcity else 110.0
        else:
            bid = max(85.0, highest_prev + 6.0)
    else:
        if scarcity:
            if rich_aggressive >= 1:
                bid = 72.0
            else:
                bid = max(58.0, min(95.0, avg_prev + 4.0))
        elif comfortable_supply:
            bid = 24.0 if rich_aggressive >= 1 else 32.0
        else:
            if highest_prev >= 140:
                bid = 30.0
            elif highest_prev >= 90:
                bid = 42.0
            else:
                bid = max(34.0, min(55.0, avg_prev + 3.0))

    if desperate_opps >= 2 and hp >= 4 and no_water_days == 0:
        bid = min(bid, 35.0)

    if day >= 8:
        if hp <= 3:
            bid = max(bid, 95.0)
        else:
            bid = min(max(bid, 40.0), 75.0)

    if budget < bid:
        if hp <= 2 or no_water_days >= 1:
            bid = budget
        else:
            bid = min(budget, bid)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline from supply pressure: with higher supply, we can bid less and still secure.
    # With lower supply, bid more to prevent being outbid.
    supply_mid = 0.5 * (MIN_SUPPLY + MAX_SUPPLY)
    supply_factor = 0.95 if supply >= supply_mid else 1.08

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If I'm already in danger, increase bid.
    danger_factor = 1.0
    if hp <= 2.0 or no_water_days >= 2:
        danger_factor = 1.25
    elif hp <= 4.0 or no_water_days == 1:
        danger_factor = 1.10

    # Use yesterday's max bid as an upper anchor (avoid Cindy-like overpay by not matching max).
    if prev_bids:
        max_prev = max(prev_bids)
        # If someone was bidding extremely high, we need to contest.
        if max_prev >= DAILY_SALARY * 0.85:
            target = DAILY_SALARY * 0.65 * supply_factor * danger_factor
            # Still cap relative to max_prev to avoid Cindy-style budget burn.
            target = min(target, max_prev * 0.85)
        else:
            # Moderate contention: bid enough to beat typical high bids but not the extreme.
            target = DAILY_SALARY * 0.55 * supply_factor * danger_factor
            # If max_prev is not too high, slightly nudge toward it.
            target = max(target, min(DAILY_SALARY * 0.65, max_prev * 0.75))
    else:
        target = DAILY_SALARY * 0.55 * supply_factor * danger_factor

    # Convert target into a bid that respects our budget.
    # Keep some budget for later days.
    reserve_ratio = 0.35 if day >= 7 else 0.25
    max_affordable = budget * (1.0 - reserve_ratio)
    if max_affordable < 0:
        max_affordable = 0.0

    bid = min(max_affordable, target)

    # Ensure non-negative and at least a minimal contest bid.
    if bid < 0:
        bid = 0.0
    min_contest = DAILY_SALARY * 0.35
    if bid < min_contest and budget >= min_contest:
        bid = min_contest

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
